// Authored bitmap VFX: frames are cropped to individual cells to prevent bleed.
export function loadVisualAssets(){if(typeof Image==='undefined')return{};const assets={};for(const [key,file]of Object.entries({impact:'impact-atlas.webp',stone:'sanctuary-stone.webp'})){const image=new Image();image.src=new URL('./assets/'+file,import.meta.url);assets[key]=image;}return assets;}
export function drawImpactSprite(r,f){const im=r.visualAssets?.impact;if(!im?.complete||!im.naturalWidth||!['impact','meteorimpact'].includes(f.type))return false;const t=Math.max(0,Math.min(.999,1-f.life/f.total)),frame=Math.min(15,Math.floor(t*16)),cell=im.naturalWidth/4,ch=im.naturalHeight/4,q=r.point(f.x,f.z,f.type==='meteorimpact'?.2:1),size=r.scale*(f.type==='meteorimpact'?Math.min(9,(f.r||3)*2.4):(f.r||1)*3.3);const c=r.ctx;c.save();c.globalCompositeOperation='lighter';c.globalAlpha=Math.min(1,(1-t)*3);c.drawImage(im,frame%4*cell,Math.floor(frame/4)*ch,cell,ch,q.x-size/2,q.y-size/2,size,size);c.restore();return true;}
